import React, { Component } from 'react';
import classes from './Tutorial.module.css';

class Tutorial extends Component {

    render() {

        let message = (

            <React.Fragment>
                <div>
                    <h3 > Tutorial: </h3>

                    <div className={classes.area}> <p> A) Connecting to the Ethereum blockchain: </p> </div>
                    <div className={classes.FirstLayer}>
                        <div className={classes.forceFlex}>
                            <p> 1. Download the Metamask extension for your browser </p>

                            <span style={{color: "black"}}> : </span>  

                            &nbsp;

                            <div>
                                <a href="https://metamask.io/"
                                   className={classes.link}>
                                    Download Metamask
                                </a>
                            </div>     
                        </div>

                        <p> 2. Create a Metamask account. </p>

                    </div>
                    <div className={classes.area}>
                        <p> B) Platform usage: </p>
                    </div>
                    <div className={classes.FirstLayer}>
                        <p> 1. As a Buyer: </p>
                        <div className={classes.SecondLayer}>
                        <p> Mierda pura </p>
                        </div>
                    </div>
                </div>
            </React.Fragment>
        )

        return (
            <div className={classes.Tutorial}>
               {message} 
            </div>
        )}
    }

export default Tutorial;
